svg.script:
document.getElementById("hunterjumper-game").srcdoc = "<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
 <meta name="color-scheme" content="dark">
 <title>HunterJumper</title>
 <style>
 * { box-sizing: border-box; }
 [hidden] { display: none !important; }
 html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
 body { background: #171b23; color: #edf2f7; font: 15px/1.6 system-ui, sans-serif; touch-action: none; }
 #canvas { display: block; width: 100%; height: 100%; outline: none; }
 #loading { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: #171b23; }
 #loading[hidden] { display: none; }
 .panel { width: min(420px, 100%); text-align: center; }
 h1 { margin: 0 0 12px; font-size: clamp(27px, 7vw, 40px); letter-spacing: -.03em; }
 #message { margin: 0 0 20px; color: #b7c3d4; overflow-wrap: anywhere; }
 progress { display: block; width: 100%; height: 12px; accent-color: #8bc8a5; }
 .small { color: #8999b0; font-size: 12px; margin: 18px 0 0; }
 a { color: #aad9bd; }
 button { margin-top: 18px; padding: 10px 18px; border: 0; border-radius: 6px; background: #aad9bd; color: #13251b; font: inherit; font-weight: 600; cursor: pointer; }
 button:focus-visible, a:focus-visible { outline: 2px solid #fff; outline-offset: 4px; }
 </style>
</head>
<body>
 <canvas id="canvas" tabindex="0" aria-label="HunterJumper game. Click or tap above the horse to jump.">
 This game needs a browser with HTML canvas and WebGL support.
 </canvas>
 <section id="loading" aria-live="polite">
 <div class="panel">
 <h1>HunterJumper</h1>
 <p id="message">Loading the game engine…</p>
 <progress id="progress" max="100" aria-label="Game download progress"></progress>
 <button id="retry" type="button" hidden>Try again</button>
 <p class="small">The first load downloads about 20 MB.<br>
 Original game by <a href="https://github.com/therabbitproject/HunterJumper" target="_blank" rel="noopener noreferrer">therabbitproject</a>.
 </p>
 </div>
 </section>
 <script>
 (() => {
 'use strict';
 // Pin the original public web export so upstream changes cannot silently break this launcher.
 const ASSET_BASE = 'https://cdn.jsdelivr.net/gh/therabbitproject/HunterJumper@52813b5f9034ba9b08274547f4f70486606d2dd6/';
 const canvas = document.getElementById('canvas');
 const loading = document.getElementById('loading');
 const message = document.getElementById('message');
 const progress = document.getElementById('progress');
 const retry = document.getElementById('retry');
 let finished = false;
 let failed = false;

 function resize() {
 const width = Math.max(1, window.innerWidth);
 const height = Math.max(1, window.innerHeight);
 if (canvas.width !== width) canvas.width = width;
 if (canvas.height !== height) canvas.height = height;
 }
 resize();
 window.addEventListener('resize', resize);
 document.addEventListener('fullscreenchange', resize);
 retry.addEventListener('click', () => window.location.reload());

 function fail(error) {
 if (failed) return;
 failed = true;
 finished = true;
 loading.hidden = false;
 progress.hidden = true;
 retry.hidden = false;
 const detail = error instanceof Error ? error.message : String(error);
 message.textContent = 'The game could not start. ' + detail;
 console.error('HunterJumper launcher:', error);
 }

 const script = document.createElement('script');
 script.src = ASSET_BASE + 'HunterJumper.js';
 script.onerror = () => fail(new Error('Could not download the game engine. Check your connection and try again.'));
 script.onload = () => {
 try {
 if (typeof window.Engine !== 'function') throw new Error('The downloaded engine is unavailable.');
 if (!window.Engine.isWebGLAvailable()) throw new Error('WebGL is unavailable. Try a browser with hardware acceleration enabled.');
 if (typeof WebAssembly !== 'object') throw new Error('This browser does not support WebAssembly.');
 const engine = new window.Engine();
 engine.setCanvas(canvas);
 engine.setProgressFunc((current, total) => {
 if (finished) return;
 if (total > 0) {
 const percent = Math.min(100, Math.floor(current / total * 100));
 progress.value = percent;
 message.textContent = percent === 100 ? 'Starting the game…' : 'Downloading the game… ' + percent + '%';
 } else {
 progress.removeAttribute('value');
 message.textContent = 'Downloading the game…';
 }
 });
 // startGame derives the matching WASM URL and writes the pack under its filename.
 engine.startGame(ASSET_BASE + 'HunterJumper.pck').then(() => {
 if (failed) return;
 engine.rtenv.onAbort = (code) => fail(new Error('The original game engine stopped (' + code + '). Try reloading or another browser.'));
 finished = true;
 loading.hidden = true;
 resize();
 }).catch(fail);
 } catch (error) {
 fail(error);
 }
 };
 document.head.appendChild(script);
 })();
 </script>
</body>
</html>
";
